"""Bounded lattice-word conditioning; no original anatomy control moves."""
from pathlib import Path
import argparse,sys,time,json
import numpy as np
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from geometry_tools.model import Mesh
from geometry_tools.common import atomic_json,atomic_npz,digest_file
from geometry_tools.audit import audit
from geometry_tools.algorithms.bounded_float32_rounding import round_diagnosed_crossings
ap=argparse.ArgumentParser();ap.add_argument('--source',default='native-pv-mouths-v66/whole-wall.npz');ap.add_argument('--audit',default='native-pv-mouths-v66/emitted-audit.json');ap.add_argument('--stage',default='native-pv-mouths-v69');args=ap.parse_args();start=time.monotonic();b=ROOT/'.local-models/geometry-workbench/heart';out=b/args.stage;out.mkdir(exist_ok=False);m=Mesh.load(b/args.source);a=Mesh.load(b/'whole-wall-v25/whole-wall.npz');o=np.array([0.,1.375,.03125]);proof=json.loads((b/args.audit).read_text());pairs=proof['self_intersections']['examples'];assert len(pairs)==proof['self_intersections']['defect_pairs'];dtype=np.dtype((np.void,12));stored=(m.vertices-o).astype('<f4').view(dtype).ravel();original=(a.vertices-o).astype('<f4').view(dtype).ravel();protected=np.flatnonzero(np.isin(stored,original));r=round_diagnosed_crossings(m.vertices,m.faces,pairs,origin=o,protected=protected,seconds=20.,maximum_moves=32);wall=Mesh(r['positions'],m.faces,m.frame);wall.save(out/'whole-wall.npz');atomic_json(out/'rounding.json',r['evidence']);print('Bounded rounding',r['evidence']['passed'],len(r['evidence']['moves']),'moves; remaining',r['evidence']['remaining_global_defect_pair_count'],flush=True);final=audit(wall,require_closed=True,max_pairs=3500000,max_tests=26000000);atomic_json(out/'emitted-audit.json',final);report=dict(passed=final['passed']and r['evidence']['passed'],source_sha256=digest_file(b/args.source),geometry_sha256=wall.geometry_sha,original_controls_protected=len(protected),rounding=r['evidence'],failures=final['failures'],self_crossings=final['self_intersections']['defect_pairs'],elapsed_seconds=time.monotonic()-start,installed=False,anatomical_acceptance=False);atomic_json(out/'construction.json',report);print(json.dumps(report),flush=True)
